content:
.desktop-ide #files-panel{display:flex;flex-direction:column}.desktop-ide #files-panel .workspace-name{padding:7px 10px;gap:6px;flex:none}.desktop-ide #files-panel #workspace-name{font-size:12px}
.desktop-ide #file-search{font-size:11px;margin:4px 7px 7px;width:calc(100% - 14px);height:25px;padding:3px 7px;flex:none}
.desktop-ide #files{flex:1;min-height:60px;overflow:auto}.desktop-ide .file-row{font-size:12px;padding-top:3px;padding-bottom:3px;min-height:26px;gap:5px}.desktop-ide .file-row span:last-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.desktop-ide .project-options{margin:0;padding:6px 8px;border:0;display:grid;gap:5px}.desktop-ide .project-options select{height:25px;padding:2px 6px;font-size:11px}
.desktop-project-properties{flex:none}.desktop-project-properties summary{font-size:11px}.desktop-ide .studio-folder>summary{font-size:12px;padding-top:4px;padding-bottom:4px}
#dev-hierarchy-panel{display:flex;flex-direction:column}#dev-tree{flex:1;min-height:85px;max-height:none;overflow:auto;display:flex;flex-direction:column;padding:4px 0}
#dev-tree button{font-size:12px;min-height:26px;text-align:left;white-space:pre;border-radius:0;padding:4px 9px}#dev-tree [aria-selected=true]{background:var(--selection);outline:none;box-shadow:inset 2px 0 var(--accent)}
.desktop-toolbox-footer{padding:6px}#desktop-toolbox-filter{margin:7px;width:calc(100% - 14px)}.desktop-ide .studio-toolbox-tiles{display:flex;flex-direction:column;padding:0;gap:0}.desktop-ide .studio-toolbox-tiles button{display:flex;gap:8px;align-items:center;min-height:28px;padding:4px 10px;text-align:left;border:0;border-radius:0;font-size:12px}
#dev-property-panel{padding:0}#studio-property-search{margin:6px;width:calc(100% - 59px);height:26px!important}#desktop-sort-properties{height:25px;padding:3px 5px}
#dev-properties{max-height:none;overflow:visible;padding:3px 0;display:flex;flex-direction:column;gap:0}#dev-properties .dev-property{display:grid;grid-template-columns:minmax(85px,1fr) minmax(65px,1.05fr) 42px;align-items:center;gap:3px;padding:3px 6px;border-bottom:1px solid var(--border);font-size:11px}
#dev-properties .dev-property>input{width:100%;height:24px;font-size:11px;padding:2px 5px}#dev-properties .dev-property>button{font-size:10px;padding:3px 5px}#dev-properties .dev-property>label{overflow:hidden;text-overflow:ellipsis}
.desktop-property-editor .dev-row{display:grid;grid-template-columns:1fr 1fr}#dev-property-name,#dev-property-value{width:100%}.desktop-property-editor button{white-space:normal;min-height:25px}
#desktop-layout-tools .design-layout-inspector{padding:7px;margin:0;border:0;border-bottom:1px solid var(--border);background:transparent}.desktop-ide #grid-designer{padding:7px;margin:0;border:0;background:transparent}
#desktop-layout-tools .design-layout-note,#grid-message{font-size:10px}.desktop-ide .grid-track-actions,.desktop-ide .grid-cell-fields{gap:4px}.desktop-ide .grid-track-actions input{max-width:85px}
.desktop-settings-grid{display:flex;flex-direction:column;gap:12px;padding:12px;align-items:stretch}.desktop-settings-grid label{display:flex;gap:7px;align-items:center;min-height:24px}.desktop-settings-grid button{height:27px;border:1px solid var(--border)}
.desktop-ide .studio-debug-window{height:100%;padding:0;max-height:none;background:var(--panel)}.desktop-ide .studio-data-table{width:100%;font-size:11px;border-collapse:collapse}.desktop-ide .studio-data-table th{position:sticky;top:0;background:var(--panel2);text-align:left;font-size:11px;font-weight:400;border-right:1px solid var(--border);border-bottom:1px solid var(--border);padding:5px 8px;z-index:2}
.desktop-ide .studio-data-table td{padding:4px 8px;border-right:1px solid var(--border);vertical-align:top}.desktop-ide .studio-data-table tr:hover td{background:var(--hover)}.desktop-ide .studio-data-table tr[aria-selected=true] td{background:var(--selection)}
.desktop-ide .studio-empty-state{margin:10px!important;font-size:11px;line-height:1.5;color:var(--muted)}.desktop-ide .studio-value{font-family:var(--mono)}
#desktop-breakpoints{display:flex;flex-direction:column}#desktop-breakpoints #studio-breakpoints{flex:1;min-height:0}#desktop-breakpoint-editor{flex:none}#desktop-breakpoint-editor input{max-width:100px}#desktop-breakpoint-editor>label{padding:6px}
.desktop-ide .studio-window-toolbar{font-size:11px;gap:5px;flex-wrap:wrap}#desktop-debug-console{display:flex;flex-direction:column}#desktop-debug-console pre{flex:1;min-height:0}
.desktop-search-results{display:flex;flex-direction:column}.desktop-search-results button{text-align:left;border-bottom:1px solid var(--border);padding:7px;display:flex;gap:10px}.desktop-search-results code{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted);font-size:11px}.desktop-search-count{padding:5px 9px;color:var(--muted);font-size:11px}
